/**
 * tests/fixtures/released-shipped-names.ts
 *
 * Every installed name that a released version of devflow shipped, from version 0.1.0 to 3.9.0,
 * and the names merged since, each marked with a comment.
 * The install-backup guards read it two ways: each name must be in the shipped set or the retired
 * set (a released file never reaches a user as an unknown file), and each name the current build
 * ships must be here (the ratchet).
 *
 * A PR that ships a new name adds it here. Extend this list, never remove from it: a release
 * cannot be un-shipped.
 *
 * Names are as installed under the Claude dir: a command, agent or rule name has no `.md`, and a
 * skill folder has its installed name (`devflow:git`, or a bare name from the first releases).
 * `skillFiles` maps a skill folder to the files below it.
 */

export interface ReleasedShippedNames {
  readonly commands: readonly string[];
  readonly agents: readonly string[];
  readonly rules: readonly string[];
  readonly skills: readonly string[];
  readonly skillFiles: Readonly<Record<string, readonly string[]>>;
}

const names = (list: readonly string[]): readonly string[] => Object.freeze([...list]);

